export class AsyncEventBus {
  constructor() {
    this._listeners = new Map();
  }

  subscribe(event, handler, priority = 0) {
    if (!this._listeners.has(event)) {
      this._listeners.set(event, []);
    }
    const record = { handler, priority };
    const list = this._listeners.get(event);
    list.push(record);
    list.sort((a, b) => b.priority - a.priority);

    // Return idempotent unsubscribe function
    return () => {
      const current = this._listeners.get(event) || [];
      this._listeners.set(event, current.filter(r => r !== record));
      if (this._listeners.get(event).length === 0) {
        this._listeners.delete(event);
      }
    };
  }

  async publish(event, payload) {
    const handlers = this._listeners.get(event) || [];
    for (const { handler } of handlers) {
      try {
        await handler(payload);
      } catch (err) {
        console.error(`Error in event listener for "${event}":`, err);
      }
    }
  }

  clear() {
    this._listeners.clear();
  }
}
